  case "proposal_store":{
   for(int dl=0;dl<2;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();await d.SeedContact();await d.SeedNeed();var actor=dl==0?d.G:d.H;await using var s=d.Scope(actor);var id=await s.Connections.GuiDeXuatAsync(d.ProposalInput());await using var db=d.Db();var r=await db.Set<YeuCauKetNoiLopHoc>().SingleAsync(x=>x.Id==id);Assert.Equal(actor,r.NguoiDeXuatId);Assert.Equal(dl==0?"ChoBenHoc":"ChoGiaSu",r.TrangThai);Assert.Single(await db.Set<KhungGioDeXuat>().Where(x=>x.YeuCauKetNoiId==id).ToListAsync());Assert.False(await db.Set<LopHoc>().AnyAsync(x=>x.YeuCauKetNoiId==id));}break;}
  case "contact_race":{
