  case "class_store":case "class_idempotent":{
   await f.SeedProposal();var v=Convert.ToBase64String(await f.Version<YeuCauKetNoiLopHoc>(f.Request));await using(var s=f.Scope(f.H))f.Class=await s.Connections.ChapNhanDeXuatAsync(f.Request,v);if(key=="class_idempotent"){await using var s=f.Scope(f.H);Assert.Equal(f.Class,await s.Connections.ChapNhanDeXuatAsync(f.Request,v));await using var a=f.Scope(f.H);await using var b=f.Scope(f.H);var ids=await Task.WhenAll(a.Connections.ChapNhanDeXuatAsync(f.Request,v),b.Connections.ChapNhanDeXuatAsync(f.Request,v));Assert.All(ids,id=>Assert.Equal(f.Class,id));}await ClassGraph(f);await using var db=f.Db();Assert.Equal("DangMo",(await db.Set<NhuCauHoc>().SingleAsync(x=>x.Id==f.Need)).TrangThai);break;}
  case "end_store":case "end_duplicate":{
   await f.SeedClass();await using var g=f.Scope(f.G);var result=await g.Connections.TaoYeuCauHuyAsync(f.Class,"Đã hoàn thành mục tiêu",await f.Version<LopHoc>(f.Class),f.G,default);Assert.True(result.ThanhCong,result.ThongBao);var id=result.DuLieu;
   if(key=="end_duplicate"){await using var h=f.Scope(f.H);var duplicate=await h.Connections.TaoYeuCauHuyAsync(f.Class,"Đã xong",await f.Version<LopHoc>(f.Class),f.H,default);Assert.False(duplicate.ThanhCong);Assert.Equal(409,duplicate.MaTrangThai);await using var db=f.Db();Assert.Single(await db.Set<YeuCauHuyKetNoi>().Where(x=>x.LopHocId==f.Class&&x.TrangThai=="ChoPhanHoi").ToListAsync());}
   else{await using var h=f.Scope(f.H);var reply=await h.Connections.PhanHoiHuyAsync(id,true,await f.Version<YeuCauHuyKetNoi>(id),f.H,default);Assert.True(reply.ThanhCong,reply.ThongDiep);await using var db=f.Db();var c=await db.Set<LopHoc>().SingleAsync(x=>x.Id==f.Class);Assert.Equal("DaKetThuc",c.TrangThai);Assert.NotNull(c.KetThucLuc);Assert.NotNull(c.CachKetThuc);Assert.Equal("Đã hoàn thành mục tiêu",(await db.Set<YeuCauHuyKetNoi>().SingleAsync(x=>x.Id==id)).LyDo);}break;}
  case "schedule_store":{
