  case "assignment_store":{
   await f.SeedLesson();await using(var g=f.Scope(f.G)){await g.Schedules.GhiNhanAsync(RecordModel(f,Convert.ToBase64String(await f.Version<BuoiHoc>(f.Lesson))));}
   var root=Path.Combine(Path.GetTempPath(),"EduConnect-IT-"+f.Tag);Directory.CreateDirectory(root);
   try{await using(var g=f.Scope(f.G)){var env=new TestEnvironment{EnvironmentName="Development",ContentRootPath=root,WebRootPath=Path.Combine(root,"wwwroot")};var cfg=new Microsoft.Extensions.Configuration.ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"FileScanning:AllowUnscannedUploads","true"}}).Build();var files=new TepService(g.Db,g.Current,g.Rights,env,configuration:cfg);Assert.True(files.ChoPhepTepChuaQuet);var service=new BaiTapService(g.Db,g.Current,g.Rights,g.Notices,files);await service.GiaoAsync(new(){LopHocId=f.Class,BuoiHocId=f.Lesson,TieuDe="Bài gắn buổi",NoiDung="Bài cần làm",TieuChiCham="Đúng nội dung",HanNopLuc=DateTime.Today.AddDays(5).AddHours(21),Files=[Pdf("assignment")]});}
    await using var verify=f.Db();var task=await verify.Set<BaiTapGiao>().SingleAsync(x=>x.LopHocId==f.Class&&x.TieuDe=="Bài gắn buổi");Assert.Equal(f.Lesson,task.BuoiHocId);Assert.Equal("DaGiao",task.TrangThai);var file=await verify.Set<TepDinhKem>().SingleAsync(x=>x.BaiTapGiaoId==task.Id);Assert.Equal(f.G,file.NguoiTaiLenId);Assert.Equal("ChoQuet",file.TrangThaiQuet);Assert.Equal(64,file.Checksum.Length);Assert.True(File.Exists(Path.Combine(root,"uploads",file.TenLuuTru)));Assert.True(await verify.Set<ThongBao>().AnyAsync(x=>x.DoiTuongId==task.Id&&x.LoaiThongBao=="BaiTap"));
   }finally{if(Directory.Exists(root))Directory.Delete(root,true);}break;}
  case "assignment_http":{
   await f.SeedLesson();await using(var g=f.Scope(f.G)){await g.Schedules.GhiNhanAsync(RecordModel(f,Convert.ToBase64String(await f.Version<BuoiHoc>(f.Lesson))));}
   f.AllowUnscannedUploads=true;using(var tutor=await f.Client(f.G)){
    var formUrl=$"/HocTap/BaiTap/Giao?id={f.Class}&buoi={f.Lesson}";var token=await Fixture.Token(tutor,formUrl);
    using var form=new MultipartFormDataContent();void Add(string name,string value)=>form.Add(new StringContent(value),name);
    Add("LopHocId",f.Class.ToString());Add("BuoiHocId",f.Lesson.ToString());Add("TieuDe","Bài multipart gắn buổi");Add("NoiDung","Nội dung giao qua form multipart");Add("TieuChiCham","Đúng nội dung");Add("HanNopLuc",DateTime.Today.AddDays(5).AddHours(21).ToString("yyyy-MM-ddTHH:mm:ss"));Add("__RequestVerificationToken",token);
    var bytes=System.Text.Encoding.ASCII.GetBytes("%PDF-1.4\nIT-102 fixture\n%%EOF");var part=new ByteArrayContent(bytes);part.Headers.ContentType=new System.Net.Http.Headers.MediaTypeHeaderValue("application/pdf");form.Add(part,"Files","lesson.pdf");
    using var response=await tutor.PostAsync("/HocTap/BaiTap/Giao",form);Assert.Equal(HttpStatusCode.Redirect,response.StatusCode);
   }
   Guid taskId;await using(var verify=f.Db()){var task=await verify.Set<BaiTapGiao>().SingleAsync(x=>x.LopHocId==f.Class&&x.TieuDe=="Bài multipart gắn buổi");taskId=task.Id;Assert.Equal(f.Lesson,task.BuoiHocId);Assert.Equal("DaGiao",task.TrangThai);var file=await verify.Set<TepDinhKem>().SingleAsync(x=>x.BaiTapGiaoId==task.Id);Assert.Equal("lesson.pdf",file.TenGoc);Assert.Equal(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.ASCII.GetBytes("%PDF-1.4\nIT-102 fixture\n%%EOF"))),file.Checksum);Assert.True(await verify.Set<ThongBao>().AnyAsync(x=>x.DoiTuongId==task.Id&&x.LoaiThongBao=="BaiTap"));}
   using(var learner=await f.Client(f.H))using(var detail=await learner.GetAsync("/HocTap/BaiTap/ChiTiet?id="+taskId)){Assert.Equal(HttpStatusCode.OK,detail.StatusCode);var body=System.Net.WebUtility.HtmlDecode(await detail.Content.ReadAsStringAsync());f.Proof["IT102DetailBody"]=body;Assert.Contains("Bài multipart gắn buổi",body,StringComparison.Ordinal);}
   break;}
  case "submission_store":case "submission_idempotent":case "submission_latest":case "grading_invalid":case "submission_grade_race":{
   await f.SeedAssignment();var op=Guid.NewGuid();await using(var h=f.Scope(f.H))await h.Tasks.NopAsync(new(){BaiTapGiaoId=f.Assignment,MaThaoTac=op,NoiDung="Lần một"});await using var db=f.Db();var first=await db.Set<BaiTapNop>().AsNoTracking().SingleAsync(x=>x.BaiTapGiaoId==f.Assignment);f.Submission=first.Id;
   if(key=="submission_idempotent"){await using(var h=f.Scope(f.H))await h.Tasks.NopAsync(new(){BaiTapGiaoId=f.Assignment,MaThaoTac=op,NoiDung="Lần một"});await using var fresh=f.Db();Assert.Single(await fresh.Set<BaiTapNop>().Where(x=>x.BaiTapGiaoId==f.Assignment).ToListAsync());break;}
   if(key=="submission_latest"){await using(var h=f.Scope(f.H))await h.Tasks.NopAsync(new(){BaiTapGiaoId=f.Assignment,MaThaoTac=Guid.NewGuid(),NoiDung="Lần hai"});await using var fresh=f.Db();var second=await fresh.Set<BaiTapNop>().SingleAsync(x=>x.BaiTapGiaoId==f.Assignment&&x.LanNop==2);await using(var g=f.Scope(f.G)){var stale=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>g.Tasks.ChamAsync(new(){BaiTapGiaoId=f.Assignment,BaiTapNopId=first.Id,Diem=8,NhanXet="Cũ"}));Assert.Contains("Chỉ chấm lần nộp mới nhất",stale.Message,StringComparison.OrdinalIgnoreCase);}await using(var g=f.Scope(f.G))await g.Tasks.ChamAsync(new(){BaiTapGiaoId=f.Assignment,BaiTapNopId=second.Id,Diem=8.25m,NhanXet="Mới nhất"});Assert.Equal(2,await fresh.Set<BaiTapNop>().CountAsync(x=>x.BaiTapGiaoId==f.Assignment));Assert.False(await fresh.Set<KetQuaChamBai>().AnyAsync(x=>x.BaiTapNopId==first.Id));break;}
   if(key=="grading_invalid"){foreach(var actor in new[]{f.H,f.X}){await using var g=f.Scope(actor);await Assert.ThrowsAsync<LoiNghiepVu>(()=>g.Tasks.ChamAsync(new(){BaiTapGiaoId=f.Assignment,BaiTapNopId=first.Id,Diem=8,NhanXet="Sai quyền"}));}foreach(var score in new[]{-0.01m,10.01m,8.251m}){await using var g=f.Scope(f.G);await Assert.ThrowsAsync<LoiNghiepVu>(()=>g.Tasks.ChamAsync(new(){BaiTapGiaoId=f.Assignment,BaiTapNopId=first.Id,Diem=score,NhanXet="Sai điểm"}));}Assert.False(await db.Set<KetQuaChamBai>().AnyAsync(x=>x.BaiTapNopId==first.Id));break;}
   if(key=="submission_grade_race"){await using var h=f.Scope(f.H);await using var g=f.Scope(f.G);var ready=0;var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);async Task<Exception?> Start(Func<Task> action){Interlocked.Increment(ref ready);await release.Task;return await Capture(action);}var submit=Start(()=>h.Tasks.NopAsync(new(){BaiTapGiaoId=f.Assignment,MaThaoTac=Guid.NewGuid(),NoiDung="Lần hai"}));var grade=Start(()=>g.Tasks.ChamAsync(new(){BaiTapGiaoId=f.Assignment,BaiTapNopId=first.Id,Diem=8,NhanXet="Chấm"}));while(Volatile.Read(ref ready)<2)await Task.Yield();release.SetResult();var both=await Task.WhenAll(submit,grade);Assert.Single(both.Where(x=>x==null));var rejected=Assert.Single(both.Where(x=>x!=null));Assert.True(rejected is LoiNghiepVu or DbUpdateConcurrencyException or Microsoft.Data.SqlClient.SqlException,rejected!.ToString());await using var fresh=f.Db();var oldGraded=await fresh.Set<KetQuaChamBai>().AnyAsync(x=>x.BaiTapNopId==first.Id);var submissionCount=await fresh.Set<BaiTapNop>().CountAsync(x=>x.BaiTapGiaoId==f.Assignment);Assert.Equal(oldGraded?1:2,submissionCount);if(oldGraded)Assert.Equal(1,await fresh.Set<KetQuaChamBai>().CountAsync(x=>x.BaiTapNopId==first.Id));else Assert.False(await fresh.Set<KetQuaChamBai>().AnyAsync(x=>x.BaiTapNopId==first.Id));break;}
   await using(var g=f.Scope(f.G))await g.Tasks.ChamAsync(new(){BaiTapGiaoId=f.Assignment,BaiTapNopId=first.Id,Diem=8.25m,NhanXet="Đã chấm"});await using(var fresh=f.Db()){var result=await fresh.Set<KetQuaChamBai>().SingleAsync(x=>x.BaiTapNopId==first.Id);Assert.Equal(8.25m,result.Diem);Assert.Equal(f.G,result.NguoiChamId);}break;}
  case "chat_store":case "chat_retry":{
   await f.SeedContact();await using var db=f.Db();var room=await db.Set<CuocHoiThoai>().Where(x=>x.LienHeId==f.Contact).Select(x=>x.Id).SingleAsync();var m=new GuiTinNhanViewModel{MaHoiThoai=room,MaThaoTac=Guid.NewGuid(),NoiDung=f.Tag};string? attachmentRoot=null;await using(var h=f.Scope(f.H)){if(key=="chat_store"){attachmentRoot=Path.Combine(Path.GetTempPath(),"EduConnect-chat-"+f.Tag);Directory.CreateDirectory(attachmentRoot);var env=new TestEnvironment{EnvironmentName="Development",ContentRootPath=attachmentRoot,WebRootPath=Path.Combine(attachmentRoot,"wwwroot")};var cfg=new Microsoft.Extensions.Configuration.ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"FileScanning:AllowUnscannedUploads","true"}}).Build();var files=new EduConnect.Mvc.Infrastructure.TepService(h.Db,h.Current,h.Rights,env,configuration:cfg);var bytes=System.Text.Encoding.ASCII.GetBytes("%PDF-1.4\nchat fixture\n%%EOF");m.Files=[new Microsoft.AspNetCore.Http.FormFile(new MemoryStream(bytes),0,bytes.Length,"Files","chat.pdf"){Headers=new Microsoft.AspNetCore.Http.HeaderDictionary(),ContentType="application/pdf"}];await new TinNhanService(h.Db,h.Current,h.Rights,files).GuiAsync(m);}else await h.Chat.GuiAsync(m);}if(key=="chat_retry"){await using(var h=f.Scope(f.H))await h.Chat.GuiAsync(m);m.NoiDung="Khác nội dung";await using(var h=f.Scope(f.H))await Assert.ThrowsAsync<LoiNghiepVu>(()=>h.Chat.GuiAsync(m));}await using var fresh=f.Db();var rows=await fresh.Set<TinNhan>().Where(x=>x.MaThaoTac==m.MaThaoTac).ToListAsync();Assert.Single(rows);Assert.Equal(f.Tag,rows[0].NoiDung);Assert.True(await fresh.Set<SuKienChoXuLy>().AnyAsync(x=>x.DuLieuToiThieu.Contains(room.ToString())));if(key=="chat_store"){var attachment=await fresh.Set<TepDinhKem>().SingleAsync(x=>x.TinNhanId==rows[0].Id);Assert.Equal("chat.pdf",attachment.TenGoc);Assert.Equal(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.ASCII.GetBytes("%PDF-1.4\nchat fixture\n%%EOF"))),attachment.Checksum);Assert.True(File.Exists(Path.Combine(attachmentRoot!,"uploads",attachment.TenLuuTru)));Directory.Delete(attachmentRoot!,true);}break;}
  case "chat_readonly":{
   await f.SeedClass();Guid room;await using(var db=f.Db())room=await db.Set<CuocHoiThoai>().Where(x=>x.LopHocId==f.Class&&x.LoaiHoiThoai=="TheoLop").Select(x=>x.Id).SingleAsync();
   var sent="Lịch sử vẫn xem được sau khi kết thúc lớp";using(var tutor=await f.Client(f.G)){using var response=await f.Post(tutor,"/HocTap/TinNhan/Gui",new(){{"MaHoiThoai",room.ToString()},{"MaThaoTac",Guid.NewGuid().ToString()},{"NoiDung",sent}},"/HocTap/LopHoc/ChiTiet/"+f.Class);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Contains("redirectUrl",await response.Content.ReadAsStringAsync(),StringComparison.Ordinal);}
   await f.Sql("UPDATE dbo.LopHoc SET TrangThai='DaKetThuc',KetThucLuc=SYSDATETIMEOFFSET(),CachKetThuc=N'DongY' WHERE Id=@c",new(){{"@c",f.Class}});
   using(var outside=await f.Client(f.X)){using var denied=await f.Post(outside,"/HocTap/TinNhan/Gui",new(){{"MaHoiThoai",room.ToString()},{"MaThaoTac",Guid.NewGuid().ToString()},{"NoiDung","Ngoài lớp"}},"/TaiKhoan/HoSo");Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}
   int endedStatus;using(var learner=await f.Client(f.H)){using var history=await learner.GetAsync("/HocTap/TinNhan/Lop?id="+room);Assert.Equal(HttpStatusCode.OK,history.StatusCode);var body=System.Net.WebUtility.HtmlDecode(await history.Content.ReadAsStringAsync());Assert.Contains(sent,body,StringComparison.Ordinal);using var rejected=await f.Post(learner,"/HocTap/TinNhan/Gui",new(){{"MaHoiThoai",room.ToString()},{"MaThaoTac",Guid.NewGuid().ToString()},{"NoiDung","Tin sau khi kết thúc"}},"/HocTap/TinNhan/Lop?id="+room);endedStatus=(int)rejected.StatusCode;}
   await using(var verify=f.Db()){Assert.Single(await verify.Set<TinNhan>().Where(x=>x.CuocHoiThoaiId==room&&x.NoiDung==sent).ToListAsync());Assert.False(await verify.Set<TinNhan>().AnyAsync(x=>x.CuocHoiThoaiId==room&&x.NoiDung=="Tin sau khi kết thúc"));}
   Assert.Equal((int)HttpStatusCode.Conflict,endedStatus);break;}
  default:throw new InvalidOperationException(key);
  }
 }
 static async Task<Exception?> Capture(Func<Task> f){try{await f();return null;}catch(Exception ex){return ex;}}
}

